/**
 * Mesh V4 creation, checked against the same evidence as the web dapp: the audited contracts' bin vectors, and a
 * plan generated by the Mesh server's own planner (tests/fixtures/v4Plan.fixture.json), with tampered copies.
 */
import { describe, expect, it } from 'vitest';
import binVectors from './fixtures/meshBinV4.vectors.json';
import planFixture from './fixtures/v4Plan.fixture.json';
import {
  BinV4ParamError, binV4Args, binV4FillUnlocking, binV4LockingBytecode, binV4ManageUnlocking, binV4OwnerUnlocking, binV4Prefix,
  binV4RedeemHex, binV4ScriptHash, parseBinV4, validateBinV4,
} from '../src/mesh/bin';
import { PlanCheckError, cidOfSha256, genesisOutputs, verifyPlan, type PlanExpect, type V4Plan } from '../src/mesh/plan';
import { cashAddressToLockingBytecode } from '../src/validation';

/* eslint-disable @typescript-eslint/no-explicit-any */
const clone = <T>(x: T): T => JSON.parse(JSON.stringify(x));

describe('MeshBinV4 encoder: parity with the contracts repo vectors', () => {
  for (const v of (binVectors as any).vectors) {
    it(v.name, () => {
      const p = parseBinV4(v.params);
      expect(binV4Args(p)).toEqual(v.args);
      expect(binV4Prefix(p)).toBe(v.prefixHex);
      expect(binV4RedeemHex(p)).toBe(v.redeemScriptHex);
      expect(binV4ScriptHash(p)).toBe(v.scriptHash);
      expect(binV4LockingBytecode(p)).toBe(v.lockingBytecodeHex);
      expect(binV4FillUnlocking(p, p.variant === 'feeSchedule' ? 1 : 0)).toBe(v.unlocking.fill);
      expect(binV4ManageUnlocking(p)).toBe(v.unlocking.manage);
      if (v.unlocking.owner1) expect(binV4OwnerUnlocking(p, 1)).toBe(v.unlocking.owner1);
      else expect(() => binV4OwnerUnlocking(p, 1)).toThrow(BinV4ParamError);
    });
  }
  for (const v of (binVectors as any).invalid) {
    it(`refuses: ${v.name}`, () => {
      const q = v.params;
      const p: any = { ...q, bidNum: BigInt(q.bidNum), bidDen: BigInt(q.bidDen), askNum: BigInt(q.askNum), askDen: BigInt(q.askDen),
        ...(q.sizeFee ? { sizeFee: { ...q.sizeFee, refSize: BigInt(q.sizeFee.refSize) } } : {}) };
      expect(() => validateBinV4(p)).toThrow(BinV4ParamError);
    });
  }
});

const plan = (planFixture as any).plan as V4Plan;
const input = (planFixture as any).input;
const expectFor = (p: V4Plan = plan): PlanExpect => ({
  category: p.category, tokenCat: input.tokenCat, ownerLock: plan.outputs[1]!.lockingBytecode, binStepBps: 100,
  maxSats: 60_000n + 4n * 1000n, maxTokens: 40n, lowIndex: 758, highIndex: 766,
});
const refuses = (mutate: (p: V4Plan) => void, msg: RegExp) => {
  const p = clone(plan);
  mutate(p);
  expect(() => verifyPlan(p, expectFor(p))).toThrow(PlanCheckError);
  expect(() => verifyPlan(p, expectFor(p))).toThrow(msg);
};

describe('verifyPlan: the server proposes, the phone checks', () => {
  it("accepts the planner's own plan and returns every bin", () => {
    expect(verifyPlan(plan, expectFor())).toHaveLength(9);
    expect(plan.metadata.uri).toBe(`ipfs://${cidOfSha256(plan.metadata.sha256)}`);
  });
  it('refuses an NFT sent to someone else', () => refuses(p => { p.outputs[1]!.lockingBytecode = '76a914' + '11'.repeat(20) + '88ac'; }, /NFT does not go to this wallet/));
  it('refuses a minting NFT', () => refuses(p => { p.outputs[1]!.token!.nft!.capability = 'minting'; }, /must be mutable/));
  it('refuses a bin address that is not its parameters', () => refuses(p => {
    const o = p.outputs.find(o => o.role === 'bin')!; o.lockingBytecode = 'aa20' + '22'.repeat(32) + '87'; p.bins[o.binIndex!]!.lockingBytecode = o.lockingBytecode;
  }, /address does not match/));
  it('refuses a cheap ask (a price off the grid)', () => refuses(p => {
    const b = p.bins.find(b => b.side === 'ask')!;
    (b.params as any).askNum = (b.params as any).bidNum; (b.params as any).askDen = (b.params as any).bidDen;
  }, /ask is not the grid price|address does not match/));
  it('refuses bins outside the range asked for, and more than the deposit', () => {
    expect(() => verifyPlan(plan, { ...expectFor(), lowIndex: 760 })).toThrow(/below the range/);
    expect(() => verifyPlan(plan, { ...expectFor(), maxSats: 50_000n })).toThrow(/bins take/);
    expect(() => verifyPlan(plan, { ...expectFor(), maxTokens: 39n })).toThrow(/token units/);
  });
  it('refuses a fat identity output and a metadata output that is not the publication', () => {
    refuses(p => { p.outputs[0]!.valueSatoshis = '50000'; }, /identity output/);
    refuses(p => { p.metadata.uri = 'ipfs://bafkreiattacker'; }, /IPFS address|BCMR publication/);
    refuses(p => { p.outputs[p.outputs.length - 1]!.valueSatoshis = '1000'; }, /must carry nothing/);
  });
  it('refuses a bin funded twice or not at all, and a manager nobody asked for', () => {
    refuses(p => { const o = p.outputs.find(o => o.role === 'bin')!; p.outputs.splice(3, 0, { ...o }); }, /funded twice/);
    refuses(p => { p.outputs = p.outputs.filter(o => !(o.role === 'bin' && o.binIndex === 8)); }, /not funded/);
    refuses(p => { (p.bins[0]!.params as any).managerHash = '44'.repeat(32); }, /manager or variant|address does not match/);
  });
  it('hands the outputs to the wallet module in plan order', () => {
    const outs = genesisOutputs(plan);
    expect(outs.map(o => o.lockingBytecode)).toEqual(plan.outputs.map(o => o.lockingBytecode));
    expect(outs[1]!.token?.nft?.capability).toBe('mutable');
  });
});

describe('cashAddressToLockingBytecode', () => {
  it("decodes the planner's owner to the script its NFT output pays", () => {
    expect(cashAddressToLockingBytecode(input.owner)).toBe(plan.outputs[1]!.lockingBytecode);
  });
  it('decodes pay-to-script-hash-32 bin addresses, plain and token-aware, and refuses bad ones', () => {
    for (const v of (binVectors as any).vectors) {
      expect(cashAddressToLockingBytecode(v.chipnet.address)).toBe(v.lockingBytecodeHex);
      expect(cashAddressToLockingBytecode(v.chipnet.tokenAddress)).toBe(v.lockingBytecodeHex);
      expect(cashAddressToLockingBytecode(v.mainnet.address)).toBe(v.lockingBytecodeHex);
    }
    expect(cashAddressToLockingBytecode(input.owner.slice(0, -1) + (input.owner.endsWith('q') ? 'p' : 'q'))).toBeNull();
    expect(cashAddressToLockingBytecode('not an address')).toBeNull();
  });
});
